sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var flowContext = new GlideRecord('sys_flow_context');//for defect MSSRBX-1055, MSSRBX-1064
	flowContext.addQuery('source_record', current.sys_id);
	flowContext.query();
	while(flowContext.next()){
		sn_fd.FlowAPI.cancel(flowContext.getUniqueValue(), 'Cancelling in-progress flows for cancelled trade case');
	}
	// MSSRBXCE-241 : Commenting Line 10-21 as this functionality is achieved by 241
