	// 	parentAggregated.addQuery('trade_case_number', current.sys_id);
	// 	parentAggregated.addEncodedQuery('aggregation_statusINDraft,Ready to be sent');
	// 	parentAggregated.query();
	// 	while(parentAggregated.next()){
	// 		childAggregated.deleteRecord();//MSSRBXSN-3363
	// 	}
	// }

})(current, previous);
